const items = $input.all();

if (!items || items.length === 0) {
  throw new Error("No hay datos de entrada en Filtros.");
}

// 1. DESEMPAQUETAR HOJA DE FILTROS
let filasFiltros = [];
if (items[0].json && Array.isArray(items[0].json.data)) {
  filasFiltros = items[0].json.data;
} else {
  filasFiltros = items.map(item => item.json);
}

function extraerFiltro(nombreColumna) {
  const objetivo = nombreColumna.toLowerCase().replace(/[\s_]/g, '');
  const resultado = [];
  for (const fila of filasFiltros) {
    for (const [clave, valor] of Object.entries(fila)) {
      const claveLimpia = clave.toLowerCase().replace(/[\s_]/g, '');
      if (claveLimpia === objetivo && valor !== null && valor !== undefined && String(valor).trim() !== '') {
        String(valor).split(',').forEach(v => {
          const limpio = v.trim().toLowerCase();
          if (limpio) resultado.push(limpio);
        });
      }
    }
  }
  return [...new Set(resultado)];
}

const rolesDeseados = extraerFiltro('rolesdeseados');
const rolesRechazados = extraerFiltro('rolesrechazados');
const keywordsRechazadas = extraerFiltro('keywordsrechazadas');
const ubicacionesValidas = extraerFiltro('ubicacionesvalidas');
const ubicacionesRechazadas = extraerFiltro('ubicacionesrechazadas');

// 2. DESEMPAQUETAR HOJA "MI_PERFIL" DINÁMICAMENTE
let perfilTexto = "";

try {
  // Leemos los datos del nodo de Sheets llamado 'Mi_Perfil'
  const itemsPerfil = $('Aggregate').all(); 

  let filasPerfil = [];
  if (itemsPerfil.length > 0) {
    if (itemsPerfil[0].json && Array.isArray(itemsPerfil[0].json.data)) {
      filasPerfil = itemsPerfil[0].json.data;
    } else {
      filasPerfil = itemsPerfil.map(i => i.json);
    }
  }

  const habilidadesEncontradas = [];

  for (const fila of filasPerfil) {
    let nombreHabilidad = '';
    let nivelHabilidad = 'Intermedio'; // Valor por defecto si no tienes columna Nivel

    for (const [clave, valor] of Object.entries(fila)) {
      const claveLimpia = clave.toLowerCase().replace(/[\s_]/g, '');
      if (claveLimpia === 'habilidad' || claveLimpia === 'skill' || claveLimpia === 'habilidades') {
        nombreHabilidad = valor;
      }
      if (claveLimpia === 'nivel' || claveLimpia === 'level') {
        nivelHabilidad = valor;
      }
    }

    if (nombreHabilidad && String(nombreHabilidad).trim() !== '') {
      habilidadesEncontradas.push(`${nombreHabilidad} (${nivelHabilidad})`.trim());
    }
  }

  if (habilidadesEncontradas.length > 0) {
    perfilTexto = "Ingeniero de Sistemas. Habilidades técnicas: " + habilidadesEncontradas.join(', ');
  } else if (filasPerfil.length > 0) {
    // Si leyó la hoja pero no encontró la columna 'Habilidad'
    const columnasPerfil = Object.keys(filasPerfil[0]);
    perfilTexto = `ERROR: n8n leyó la hoja Mi_Perfil pero no encontró la columna. Columnas detectadas: [${columnasPerfil.join(', ')}]`;
  } else {
    perfilTexto = "ERROR: El nodo Mi_Perfil no entregó datos.";
  }

} catch (e) {
  perfilTexto = `ERROR LEYENDO NODO Mi_Perfil: Verifica que el nodo de Sheets se llame exactamente 'Mi_Perfil'. Detalle: ${e.message}`;
}

return [{
  json: {
    rolesDeseados,
    rolesRechazados,
    keywordsRechazadas,
    ubicacionesValidas,
    ubicacionesRechazadas,
    perfilString: perfilTexto
  }
}];

// 1. Lectura de filtros desde Sheets
const filtros = $('Code in JavaScript').first().json || {};

const limpiar = arr => (arr || [])
  .map(x => String(x).toLowerCase().trim())
  .filter(x => x.length > 0);

const rolesDeseados = limpiar(filtros.rolesDeseados);
const rolesRechazados = limpiar(filtros.rolesRechazados);
const keywordsRechazadas = limpiar(filtros.keywordsRechazadas);
const ubicacionesValidas = limpiar(filtros.ubicacionesValidas);
const ubicacionesRechazadas = limpiar(filtros.ubicacionesRechazadas);

// Si la lista no llegó de Sheets, paramos para evitar falsos positivos
if (rolesDeseados.length === 0) {
  return [{
    json: {
      ALERTA: "rolesDeseados llegó vacío. Haz clic en 'Test step' en el nodo 'Code in JavaScript' primero.",
      filtrosRecibidos: filtros
    }
  }];
}

const items = $input.all();
const aprobados = [];

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function coincide(patron, texto) {
  if (!patron || !texto) return false;
  if (patron.includes(' ')) {
    return texto.includes(patron);
  }
  return new RegExp(`\\b${escapeRegex(patron)}\\b`, 'i').test(texto);
}

for (const item of items) {
  const job = item.json;

  const titulo = (job.titulo || job.title || job.jobTitle || job.name || '').toLowerCase();
  const descripcion = (job.descripcionLimpia || job.description || job.jobDescription || job.contents || '').toLowerCase();
  const ubicacion = (job.ubicacion || job.candidate_required_location || job.jobGeo || job.locations?.[0]?.name || '').toLowerCase();
  const textoCompleto = `${titulo} ${descripcion}`;

  if (!titulo && !descripcion) continue;

  // 1. Descarte por ubicación rechazada
  if (ubicacionesRechazadas.length > 0) {
    const esVetada = ubicacionesRechazadas.some(ub => coincide(ub, ubicacion));
    if (esVetada) continue;
  }

  // 2. Filtro por ubicación válida
  if (ubicacionesValidas.length > 0) {
    const esValida = ubicacionesValidas.some(ub => coincide(ub, ubicacion));
    if (!esValida) continue;
  }

  // 3. Descarte por rol no deseado en el título (senior, lead, etc.)
  if (rolesRechazados.length > 0) {
    const tieneRolRechazado = rolesRechazados.some(rol => coincide(rol, titulo));
    if (tieneRolRechazado) continue;
  }

  // 4. Descarte por keyword rechazada en el texto (3+ years, etc.)
  if (keywordsRechazadas.length > 0) {
    const tieneKeywordRechazada = keywordsRechazadas.some(kw => coincide(kw, textoCompleto));
    if (tieneKeywordRechazada) continue;
  }

  // 5. EVALUACIÓN ESTRICTA: El rol deseado DEBE estar en el TÍTULO, jamás en la descripción
  const rolCoincidente = rolesDeseados.find(rol => coincide(rol, titulo));
  if (!rolCoincidente) {
    continue;
  }

  // Aprobado
  aprobados.push({
    json: {
      id: job.id || Math.random().toString(36).substring(7),
      fuente: job.fuente || 'API',
      titulo: job.titulo || job.title || job.jobTitle || job.name,
      empresa: job.empresa || job.company_name || job.companyName || job.company?.name || 'Confidencial',
      url: job.url || job.refs?.landing_page || '',
      ubicacion: job.ubicacion || job.candidate_required_location || job.jobGeo || 'No especificada',
      motivo_aprobacion: `Coincide con rol deseado: '${rolCoincidente}' en el título`,
      descripcionLimpia: (descripcion || '').replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim().slice(0, 2000)
    }
  });
}


return aprobados;

