const items = $input.all();
const resultados = [];

for (let i = 0; i < items.length; i++) {
  const respuestaGroq = items[i].json;
  // Recuperamos la info original de la vacante desde el nodo Limit
  const trabajoOriginal = $('Limit').all()[i].json;

  let evaluacion = {};
  try {
    evaluacion = JSON.parse(respuestaGroq.choices[0].message.content);
  } catch (e) {
    evaluacion = {
      match_score: 0,
      aplica: false,
      resumen_fit: "Error al parsear respuesta",
      habilidades_faltantes: [],
      habilidades_coincidentes: []
    };
  }

  resultados.push({
    json: {
      id: trabajoOriginal.id,
      titulo: trabajoOriginal.titulo,
      empresa: trabajoOriginal.empresa,
      url: trabajoOriginal.url,
      ubicacion: trabajoOriginal.ubicacion,
      match_score: evaluacion.match_score,
      aplica: evaluacion.aplica,
      resumen_fit: evaluacion.resumen_fit,
      habilidades_faltantes: evaluacion.habilidades_faltantes || [],
      habilidades_coincidentes: evaluacion.habilidades_coincidentes || []
    }
  });
}

return resultados;

const items = $input.all();
const skillsAplanadas = [];
const fechaHoy = new Date().toISOString().split('T')[0];

for (const item of items) {
  const job = item.json;
  if (job.habilidades_faltantes && Array.isArray(job.habilidades_faltantes)) {
    for (const skill of job.habilidades_faltantes) {
      skillsAplanadas.push({
        json: {
          Habilidad_Faltante: skill.trim(),
          Trabajo: `${job.titulo} (${job.empresa})`,
          URL: job.url,
          Fecha: fechaHoy
        }
      });
    }
  }
}

return skillsAplanadas;

const items = $input.all();

if (items.length === 0) {
  return [{
    json: {
      mensaje: "🔍 *Radar Laboral*: Hoy no se encontraron vacantes con match superior al 65%."
    }
  }];
}

let cuerpo = `🚀 *Radar de Oportunidades Laborales (${items.length} encontradas)*\n\n`;

items.forEach((item, index) => {
  const job = item.json;
  cuerpo += `*${index + 1}. ${job.titulo}* en *${job.empresa}*\n`;
  cuerpo += `🎯 *Match:* ${job.match_score}%\n`;
  cuerpo += `📍 *Ubicación:* ${job.ubicacion || 'Remoto'}\n`;
  cuerpo += `💡 *Fit:* ${job.resumen_fit}\n`;
  if (job.habilidades_coincidentes && job.habilidades_coincidentes.length > 0) {
    cuerpo += `✅ *Match técnico:* ${job.habilidades_coincidentes.join(', ')}\n`;
  }
  cuerpo += `🔗 [Ver vacante](${job.url})\n\n`;
});

return [{
  json: {
    mensaje: cuerpo
  }
}];

