const items = $input.all();
const resultados = [];

// Manejar si viene envuelto en "data" (estándar de JSON:API)
let jobs = [];
if (items[0].json && Array.isArray(items[0].json.data)) {
  jobs = items[0].json.data;
} else {
  jobs = items.map(i => i.json);
}

for (const job of jobs) {
  const attr = job.attributes || {};

  // 1. URL GARANTIZADA
  const url = `https://www.getonbrd.com/jobs/${job.id}`;

  // 2. DESCRIPCIÓN EXACTA
  const partesDesc = [
    attr.description_headline,
    attr.description,
    attr.projects,
    attr.functions_headline,
    attr.functions,
    attr.benefits_headline,
    attr.benefits,
    attr.desirable_headline,
    attr.desirable
  ].filter(Boolean).join(' '); 

  const descripcionLimpia = partesDesc.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();

  // 3. UBICACIÓN DINÁMICA (Con el salvavidas de la URL que sugeriste)
  let ubicacion = '';

  let pais = '';
  if (attr.country) {
    pais = typeof attr.country === 'object' ? attr.country.name : attr.country;
  }

  // A. Primero intentamos lo oficial (si es remoto o trae país)
  if (attr.remote || attr.remote_zone) {
    ubicacion = attr.remote_zone ? `Remote (${attr.remote_zone})` : 'Remote';
  } else if (pais) {
    ubicacion = pais;
  } else {
    // B. PLAN DE RESCATE: Buscar la ciudad en la URL (job.id)
    const idStr = (job.id || '').toLowerCase();

    if (idStr.includes('bogota')) ubicacion = 'Bogotá, Colombia';
    else if (idStr.includes('medellin')) ubicacion = 'Medellín, Colombia';
    else if (idStr.includes('santiago')) ubicacion = 'Santiago, Chile';
    else if (idStr.includes('lima')) ubicacion = 'Lima, Perú';
    else if (idStr.includes('buenos-aires')) ubicacion = 'Buenos Aires, Argentina';
    else if (idStr.includes('mexico') || idStr.includes('cdmx')) ubicacion = 'México';
    else if (idStr.includes('montevideo')) ubicacion = 'Montevideo, Uruguay';
    else if (idStr.includes('quito')) ubicacion = 'Quito, Ecuador';
    else if (idStr.includes('remote') || idStr.includes('remoto')) ubicacion = 'Remote';
    else ubicacion = 'No especificada';
  }

  // 4. EMPRESA
  let empresa = 'Confidencial';
  if (job.relationships?.company?.data?.id) {
     empresa = job.relationships.company.data.id.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  } else if (attr.company?.data?.attributes?.name) {
     empresa = attr.company.data.attributes.name;
  }

  resultados.push({
    json: {
      id: job.id,
      fuente: 'GetOnBoard',
      titulo: attr.title || 'Sin título',
      empresa: empresa,
      url: url,
      ubicacion: ubicacion,
      descripcionLimpia: descripcionLimpia
    }
  });
}

return resultados;

const items = $input.all();
const nuevosJobs = [];

const jobUrlRegex = /https:\/\/www\.linkedin\.com\/(?:comm\/)?jobs\/view\/\d+[^\s]*/i;

const lineasIgnoradas = new Set([
  'Solicitar con perfil y CV',
  'Solicitud sencilla'
]);

for (const item of items) {
  const texto = String(
    item.json.textPlain || item.json.snippet || ''
  ).replace(/\r/g, '');

  const msgId = item.json.id || Date.now();
  const lineas = texto
    .split('\n')
    .map(linea => linea.trim())
    .filter(Boolean);

  for (let i = 0; i < lineas.length; i++) {
    const coincidencia = lineas[i].match(jobUrlRegex);

    if (!coincidencia) {
      continue;
    }

    const url = coincidencia[0];

    const contexto = lineas
      .slice(Math.max(0, i - 6), i)
      .filter(linea =>
        !linea.startsWith('Ver anuncio de empleo') &&
        !lineasIgnoradas.has(linea) &&
        !/^[-]+$/.test(linea)
      );

    if (contexto.length < 3) {
      continue;
    }

    let ubicacion = contexto[contexto.length - 1];
    const empresa = contexto[contexto.length - 2];
    const titulo = contexto[contexto.length - 3];

    // Verifica si la modalidad remota se mencionó en las líneas cercanas
    const textoContexto = contexto.join(' ').toLowerCase();
    if ((textoContexto.includes('remoto') || textoContexto.includes('remote')) && !ubicacion.toLowerCase().includes('remot')) {
        ubicacion += ' (Remoto)';
    }

    nuevosJobs.push({
      json: {
        id: `linkedin_${msgId}_${i}`,
        fuente: 'LinkedIn Email',
        titulo,
        empresa,
        url,
        ubicacion,
        descripcionLimpia: contexto.join(' ')
      }
    });
  }
}

return nuevosJobs;
